"use client";

import { useEffect, Suspense } from "react";
import { Card, Button, Badge, Text, Heading } from "@whop/react/components";
import { CheckIcon, Cross2Icon } from "@radix-ui/react-icons";
import { motion } from "framer-motion";
import { useAppStore, type SocialConnection } from "@/lib/store";
import { useSearchParams } from "next/navigation";

function SocialConnectionsContent() {
	const { socialConnections, setSocialConnection, removeSocialConnection } = useAppStore();
	const searchParams = useSearchParams();
	const youtubeOAuthEnabled = process.env.NEXT_PUBLIC_YOUTUBE_OAUTH_ENABLED === "true";
	const instagramOAuthEnabled = process.env.NEXT_PUBLIC_INSTAGRAM_OAUTH_ENABLED === "true";

	// Check for OAuth callback success
	useEffect(() => {
		const connected = searchParams.get("connected");
		const error = searchParams.get("error");

		if (connected) {
			// Update connection status based on OAuth callback
			const platform = connected as "youtube" | "instagram" | "tiktok";
			const username = searchParams.get("username") || `${platform.charAt(0).toUpperCase() + platform.slice(1)} User`;
			const profilePicture = searchParams.get("profilePicture") || undefined;
			setSocialConnection({
				platform,
				connected: true,
				username,
				profilePicture,
			});
			// Clean up URL
			window.history.replaceState({}, "", window.location.pathname);
		}

		if (error) {
			if (error === "youtube_oauth_disabled") {
				alert("YouTube OAuth is disabled in this environment.");
			} else if (error === "instagram_oauth_disabled") {
				// Instagram can work with access token, so silently mark as connected
				setSocialConnection({
					platform: "instagram",
					connected: true,
					username: "Instagram User",
				});
			} else if (error === "invalid_app_id") {
				alert("Invalid Instagram App ID. Please check your environment variables and ensure you're using the Instagram App ID from Meta App Dashboard (not Facebook App ID).");
			} else if (error === "invalid_redirect_uri") {
				alert("Invalid redirect URI. Please check:\n1. NEXT_PUBLIC_APP_URL is set correctly in environment variables\n2. Redirect URI matches EXACTLY what's in Instagram App Dashboard\n3. No trailing slashes in the redirect URI\n\nCheck server logs for the exact redirect URI being used.");
			} else if (error === "oauth_init_failed") {
				alert("Failed to initiate Instagram OAuth. Please check:\n1. Instagram product is added to your app\n2. Business Login is configured\n3. Redirect URI is whitelisted in Instagram App settings");
			} else if (error === "invalid_platform_app" || error.includes("platform app")) {
				alert("Invalid platform app error. This usually means:\n1. Instagram product is not added to your Meta App\n2. Business Login is not configured\n3. Wrong Instagram App ID\n\nPlease check your Meta App Dashboard configuration.");
			} else if (error.includes("redirect_uri") || error.includes("Invalid redirect")) {
				alert("Redirect URI mismatch! The redirect URI must match EXACTLY what's configured in Instagram App Dashboard.\n\nCheck:\n1. Server logs for the redirect URI being used\n2. Instagram App Dashboard → Business login settings → OAuth redirect URIs\n3. Make sure NEXT_PUBLIC_APP_URL is set correctly");
			} else {
				alert(`OAuth error: ${error}`);
			}
			// Clean up URL
			window.history.replaceState({}, "", window.location.pathname);
		}
	}, [searchParams, setSocialConnection]);

	// Refresh TikTok username if it's still showing "TikTok User" or missing
	useEffect(() => {
		const tiktokConnection = socialConnections.find(
			(conn) => conn.platform === "tiktok" && conn.connected && (!conn.username || conn.username === "TikTok User" || conn.username.trim() === "")
		);

		if (tiktokConnection) {
			// Try to refresh the username from the API
			fetch("/api/auth/tiktok/refresh-username", {
				credentials: "include",
			})
				.then((res) => {
					if (!res.ok) {
						throw new Error(`HTTP error! status: ${res.status}`);
					}
					return res.json();
				})
				.then((data) => {
					if (data.username && data.username !== "TikTok User" && data.username.trim() !== "") {
						// Preserve existing connection data
						const existingConnection = socialConnections.find((c) => c.platform === "tiktok");
						setSocialConnection({
							platform: "tiktok",
							connected: true,
							username: data.username,
							profilePicture: data.profilePicture,
							accessToken: existingConnection?.accessToken,
							refreshToken: existingConnection?.refreshToken,
							expiresAt: existingConnection?.expiresAt,
							userPlatformId: existingConnection?.userPlatformId,
						});
					}
				})
				.catch((error) => {
					console.error("Failed to refresh TikTok username:", error);
				});
		}
	}, [socialConnections, setSocialConnection]);

	const handleConnect = async (platform: "youtube" | "instagram" | "tiktok") => {
		// For Instagram, handle iframe restrictions
		// Instagram blocks OAuth in iframes, so we need special handling
		if (platform === "instagram") {
			try {
				// Check if we're in an iframe
				const isInIframe = window.self !== window.top;
				
				if (isInIframe) {
					// In iframe - open in new window to avoid blocking
					const width = 600;
					const height = 700;
					const left = (window.screen.width - width) / 2;
					const top = (window.screen.height - height) / 2;
					window.open(
						`/api/auth/${platform}`,
						"Instagram OAuth",
						`width=${width},height=${height},left=${left},top=${top},resizable=yes,scrollbars=yes`
					);
				} else {
					// Not in iframe - use direct redirect (will use HTTP 302)
					window.location.href = `/api/auth/${platform}`;
				}
			} catch (error) {
				// Fallback: open in new window if we can't determine iframe status
				console.warn("Cannot determine iframe status, opening in new window:", error);
				const width = 600;
				const height = 700;
				const left = (window.screen.width - width) / 2;
				const top = (window.screen.height - height) / 2;
				window.open(
					`/api/auth/${platform}`,
					"Instagram OAuth",
					`width=${width},height=${height},left=${left},top=${top},resizable=yes,scrollbars=yes`
				);
			}
		} else {
			// For other platforms, use normal redirect
			window.location.href = `/api/auth/${platform}`;
		}
	};

	const handleDisconnect = (platform: "youtube" | "instagram" | "tiktok") => {
		if (confirm(`Are you sure you want to disconnect ${platform}?`)) {
			removeSocialConnection(platform);
		}
	};

	const platforms = [
		{
			name: "YouTube",
			key: "youtube" as const,
			color: "red" as const,
			icon: "📺",
		},
		{
			name: "Instagram",
			key: "instagram" as const,
			color: "purple" as const,
			icon: "📷",
		},
		{
			name: "TikTok",
			key: "tiktok" as const,
			color: "gray" as const,
			icon: "🎵",
		},
	];

	const connectedAccounts = socialConnections.filter((conn) => conn.connected && conn.username);

	return (
		<Card size="3" variant="surface" className="p-4 sm:p-6">
			<Heading size="4" as="h2" className="mb-3 sm:mb-4 text-gray-12 dark:text-gray-12 sm:text-5">
				Social Media Connections
			</Heading>
			<Text size="2" color="gray" className="mb-4 text-gray-11 dark:text-gray-11 sm:text-3">
				Connect your social media accounts to enable cross-posting
			</Text>
			{connectedAccounts.length > 0 && (
				<div className="mb-6 p-3 rounded-lg border border-green-a6 bg-green-a2 dark:bg-green-a3">
					<Text size="2" weight="medium" className="mb-2 block text-gray-12 dark:text-gray-12">
						Currently Connected ({connectedAccounts.length})
					</Text>
					<div className="flex flex-wrap gap-2">
						{connectedAccounts.map((conn) => (
							<div
								key={conn.platform}
								className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-white dark:bg-gray-a4 border border-green-a6"
							>
								{conn.profilePicture && (
									<img
										src={conn.profilePicture}
										alt={`${conn.username} profile`}
										className="w-5 h-5 rounded-full object-cover"
									/>
								)}
								<Text size="1" weight="medium" className="capitalize text-gray-12 dark:text-gray-12">
									{conn.platform}:
								</Text>
								<Text size="1" className="text-gray-11 dark:text-gray-11 font-mono">
									@{conn.username}
								</Text>
							</div>
						))}
					</div>
				</div>
			)}
			<div className="grid grid-cols-1 gap-3 sm:gap-4 sm:grid-cols-2 lg:grid-cols-3">
				{platforms.map((platform) => {
					const connection = socialConnections.find((c: SocialConnection) => c.platform === platform.key);
					const isConnected = connection?.connected || false;
					const isYoutube = platform.key === "youtube";
					const isInstagram = platform.key === "instagram";
					// Check OAuth availability
					// Instagram always available since we can use access token for analytics
					const oauthAvailable = isYoutube 
						? youtubeOAuthEnabled // Use environment variable for YouTube
						: true; // Instagram and TikTok always available

					return (
						<motion.div
							key={platform.key}
							initial={{ opacity: 0, y: 20 }}
							animate={{ opacity: 1, y: 0 }}
							whileHover={{ scale: 1.02 }}
						>
							<Card
								size="2"
								variant="surface"
								className={`p-4 h-full ${
									isConnected ? "border-green-6 bg-green-a2" : "border-gray-a4"
								}`}
							>
								<div className="flex flex-col items-center gap-3">
									{connection?.profilePicture ? (
										<img
											src={connection.profilePicture}
											alt={`${connection.username || platform.name} profile`}
											className="w-16 h-16 rounded-full object-cover border-2 border-gray-a6"
										/>
									) : (
										<div className="text-4xl">{platform.icon}</div>
									)}
									<Heading size="4" as="h3" className="text-gray-12 dark:text-gray-12">
										{platform.name}
									</Heading>
									{isConnected ? (
										<>
											<Badge color="green" size="2" variant="soft">
												<CheckIcon className="mr-1" />
												Connected
											</Badge>
											{connection?.username ? (
												<div className="flex flex-col items-center gap-0.5">
													<Text size="2" weight="medium" className="text-gray-12 dark:text-gray-12">
														@{connection.username}
													</Text>
													<Text size="1" color="gray" className="text-gray-11 dark:text-gray-11">
														{platform.name} Account
													</Text>
												</div>
											) : (
												<Text size="2" color="gray" className="text-gray-11 dark:text-gray-11">
													{platform.name} Connected
												</Text>
											)}
											<Button
												variant="ghost"
												color="red"
												size="2"
												onClick={() => handleDisconnect(platform.key)}
											>
												<Cross2Icon className="mr-1" />
												Disconnect
											</Button>
										</>
									) : oauthAvailable ? (
										<Button
											color={platform.color}
											size="2"
											variant="solid"
											onClick={() => handleConnect(platform.key)}
											className="w-full"
										>
											Connect {platform.name}
										</Button>
									) : (
										<div className="flex flex-col items-center gap-1">
											<Badge color="yellow" size="2" variant="soft">
												Coming soon
											</Badge>
											<Text size="2" color="gray" className="text-center text-gray-11 dark:text-gray-11">
												{platform.name} integration is coming soon.
											</Text>
										</div>
									)}
								</div>
							</Card>
						</motion.div>
					);
				})}
			</div>
		</Card>
	);
}

export function SocialConnections() {
	return (
		<Suspense fallback={
			<Card size="3" variant="surface" className="p-6">
				<Text size="3" color="gray" className="text-gray-11 dark:text-gray-11">Loading connections...</Text>
			</Card>
		}>
			<SocialConnectionsContent />
		</Suspense>
	);
}

